import { tv } from "tailwind-variants";

const popover = tv({
  slots: {
    trigger: "",
    portal: "",
    backdrop: "",
    positioner: "",
    popup: [
      "relative flex h-(--popup-height,auto) w-(--popup-width,auto) max-w-full origin-(--transform-origin) flex-col gap-1.5 rounded-md border border-border bg-popover p-3 text-popover-foreground shadow-md transition-[scale,opacity] duration-200 ease-default outline-none",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
    ],
    arrow: [
      "relative block h-1.5 w-3 overflow-clip",
      "before:absolute before:bottom-0 before:left-1/2 before:h-[calc(6px*sqrt(2))] before:w-[calc(6px*sqrt(2))] before:transform-[translate(-50%,50%)_rotate(45deg)] before:border before:border-border before:bg-popover before:content-['']",
      "data-[side=bottom]:-top-1.5",
      "data-[side=inline-end]:-inset-s-2.25 data-[side=inline-end]:-rotate-90",
      "data-[side=inline-start]:-inset-e-2.25 data-[side=inline-start]:rotate-90",
      "data-[side=left]:-right-2.25 data-[side=left]:rotate-90",
      "data-[side=right]:-left-2.25 data-[side=right]:-rotate-90",
      "data-[side=top]:-bottom-1.5 data-[side=top]:rotate-180",
    ],
    viewport: "",
    title: "text-sm font-semibold",
    description: "text-sm text-muted-foreground",
    close: "",
  },
});

export { popover };

"use client";

import { useDirection } from "@base-ui/react";
import { Popover as BasePopover } from "@base-ui/react/popover";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { popover } from "./popover.style";

const POSITIONER_SIDE_OFFSET = 8;

const createPopoverHandle = BasePopover.createHandle;

function Popover(props: BasePopover.Root.Props) {
  return <BasePopover.Root {...props} />;
}

function PopoverTrigger({ className, ...props }: BasePopover.Trigger.Props) {
  return (
    <BasePopover.Trigger
      data-slot="popover-trigger"
      className={mergeSlotClassName(popover().trigger, className)}
      {...props}
    />
  );
}

function PopoverPortal({ className, ...props }: BasePopover.Portal.Props) {
  const direction = useDirection();

  return (
    <BasePopover.Portal
      data-slot="popover-portal"
      className={mergeSlotClassName(popover().portal, className)}
      {...props}
      dir={direction}
    />
  );
}

function PopoverBackdrop({ className, ...props }: BasePopover.Backdrop.Props) {
  return (
    <BasePopover.Backdrop
      data-slot="popover-backdrop"
      className={mergeSlotClassName(popover().backdrop, className)}
      {...props}
    />
  );
}

function PopoverPositioner({
  className,
  sideOffset = POSITIONER_SIDE_OFFSET,
  ...props
}: BasePopover.Positioner.Props) {
  return (
    <BasePopover.Positioner
      data-slot="popover-positioner"
      className={mergeSlotClassName(popover().positioner, className)}
      sideOffset={sideOffset}
      {...props}
    />
  );
}

function PopoverPopup({ className, ...props }: BasePopover.Popup.Props) {
  return (
    <BasePopover.Popup
      data-slot="popover-popup"
      className={mergeSlotClassName(popover().popup, className)}
      {...props}
    />
  );
}

function PopoverArrow({ className, ...props }: BasePopover.Arrow.Props) {
  return (
    <BasePopover.Arrow
      data-slot="popover-arrow"
      className={mergeSlotClassName(popover().arrow, className)}
      {...props}
    />
  );
}

function PopoverViewport({ className, ...props }: BasePopover.Viewport.Props) {
  return (
    <BasePopover.Viewport
      data-slot="popover-viewport"
      className={mergeSlotClassName(popover().viewport, className)}
      {...props}
    />
  );
}

function PopoverTitle({ className, ...props }: BasePopover.Title.Props) {
  return (
    <BasePopover.Title
      data-slot="popover-title"
      className={mergeSlotClassName(popover().title, className)}
      {...props}
    />
  );
}

function PopoverDescription({
  className,
  ...props
}: BasePopover.Description.Props) {
  return (
    <BasePopover.Description
      data-slot="popover-description"
      className={mergeSlotClassName(popover().description, className)}
      {...props}
    />
  );
}

function PopoverClose({ className, ...props }: BasePopover.Close.Props) {
  return (
    <BasePopover.Close
      data-slot="popover-close"
      className={mergeSlotClassName(popover().close, className)}
      {...props}
    />
  );
}

export {
  createPopoverHandle,
  Popover,
  PopoverTrigger,
  PopoverPortal,
  PopoverBackdrop,
  PopoverPositioner,
  PopoverPopup,
  PopoverArrow,
  PopoverViewport,
  PopoverTitle,
  PopoverDescription,
  PopoverClose,
};
